TION"}, {"id": "fragment-6d2cde23f44ca0d86ca2", "kind": "state_variable", "name": "FantomToken.tokensPerEth"}, {"id": "fragment-c97e70781aa2f0f7a285", "kind": "state_variable", "name": "FantomToken.numberWhitelisted"}, {"id": "fragment-a50ad2f52d71f7cd252f", "kind": "state_variable", "name": "FantomToken.whitelist"}, {"id": "fragment-40878f6e165b97389d2f", "kind": "state_variable", "name": "FantomToken.tokensTradeable"}, {"id": "fragment-dc37f54b1b5546a2f9cc", "kind": "state_variable", "name": "FantomToken.isMigrationPhaseOpen"}, {"id": "fragment-829519d7254089dde500", "kind": "state_variable", "name": "FantomToken.balancesMinted"}, {"id": "fragment-818a2a60c8ff3c92dc39", "kind": "state_variable", "name": "FantomToken.balancesMintedByType"}, {"id": "fragment-8508e9fd2b766ac7ec98", "kind": "state_variable", "name": "FantomToken.MINIMUM_CONTRIBUTION"}, {"id": "fragment-b47648073aaddb7c2ce1", "kind": "state_variable", "name": "FantomToken.balancesMain"}, {"id": "fragment-1e9e0eb19b9e6cf0e2b6", "kind": "state_variable", "name": "FantomToken.ethContributed"}, {"id": "fragment-7a78356ab9d50b14ca34", "kind": "state_variable", "name": "FantomToken.tokensMain"}, {"id": "fragment-43013883a46af1d8bc5b", "kind": "state_variable", "name": "FantomToken.totalEthContributed"}], "provided_context": [{"id": "fragment-255498ad02a5c50f9a32", "kind": "function", "name": "buyTokens()", "source": "function buyTokens() private {

        require(isMain());
        require(msg.value >= MINIMUM_CONTRIBUTION);
        require(whitelist[msg.sender]);

        uint tokens_available = TOKEN_MAIN_CAP.sub(tokensMain);

        // adjust tokens_available on first day, if necessary
        if (isMainFirstDay()) {
            uint tokens_available_first_day = firstDayTokenLimit().sub(balancesMain[msg.sender]);
            if (tokens_available_first_day < tokens_available) {
                tokens_available = tokens_available_first_day;
            }
        }

        require (tokens_available > 0);

        uint tokens_requested = ethToTokens(msg.value);
        uint tokens_issued = tokens_requested;

        uint eth_contributed = msg.value;
        uint eth_returned;

        if (tokens_requested > tokens_available) {
            tokens_issued = tokens_available;
            eth_returned = tokensToEth(tokens_requested.sub(tokens_available));
            eth_contributed = msg.value.sub(eth_returned);
        }

        balances[msg.sender] = balances[msg.sender].add(tokens_issued);
        balancesMain[msg.sender] = balancesMain[msg.sender].add(tokens_issued);
        tokensMain = tokensMain.add(tokens_issued);
        tokensIssuedTotal = tokensIssuedTotal.add(tokens_issued);

        ethContributed[msg.sender] = ethContributed[msg.sender].add(eth_contributed);
        totalEthContributed = totalEthContributed.add(eth_contributed);

        // ether transfers
        if (eth_returned > 0) msg.sender.transfer(eth_returned);
        wallet.transfer(eth_contributed);

        // log
        emit Transfer(0x0, msg.sender, tokens_issued);
        emit RegisterContribution(msg.sender, tokens_issued, eth_contributed, eth_returned);
    }"}, {"id": "fragment-cdcef8f6c8e3206d3e67", "kind": "function", "name": "setWallet(address)", "source": "function setWallet(address _wallet) public onlyOwner {
        require(_wallet != address(0x0));
        wallet = _wallet;
        emit WalletUpdated(_wallet);
    }"}, {"id": "fragment-406627fe3996d03dec94", "kind": "state_variable", "name": "Wallet.wallet", "source": "address public wallet"}, {"id": "fragment-350d8c68e9f0f24861e9", "kind": "function", "name": "availableToMint()", "source": "function availableToMint() public view returns (uint) {
        return MAX_TOTAL_TOKEN_SUPPLY.sub(TOKEN_MAIN_CAP).sub(tokensMinted);
    }"}, {"id": "fragment-25c37eef1c0f0e10f201", "kind": "function", "name": "ethToTokens(uint256)", "source": "function ethToTokens(uint _eth) public view returns (uint tokens) {
        tokens = _eth.mul(tokensPerEth);
    }"}, {"id": "fragment-5c1ddd45e7260ed4d7ac", "kind": "function", "name": "mintTokens(uint256,address,uint256)", "source": "function mintTokens(uint _mint_type, address _account, uint _tokens) public onlyOwner {
        pMintTokens(_mint_type, _account, _tokens, 0);
    }"}], "context_complete": false}

