en.tokensMain"}, {"id": "fragment-43013883a46af1d8bc5b", "kind": "state_variable", "name": "FantomToken.totalEthContributed"}], "provided_context": [{"id": "fragment-60dd8e831f07c11484d8", "kind": "function", "name": "sub(uint256,uint256)", "source": "function sub(uint a, uint b) internal pure returns (uint c) {
