agment-c5838278c8a1179dfc6e", "kind": "state_variable", "name": "FantomToken.TOKEN_MAIN_CAP"}, {"id": "fragment-6dfe9f3e3d3ce5f9fa94", "kind": "state_variable", "name": "FantomToken.tokensMinted"}, {"id": "fragment-d171a26a45811e6c8bc1", "kind": "state_variable", "name": "FantomToken.MAXIMUM_FIRST_DAY_CONTRIBUTION"}, {"id": "fragment-6d2cde23f44ca0d86ca2", "kind": "state_variable", "name": "FantomToken.tokensPerEth"}, {"id": "fragment-c97e70781aa2f0f7a285", "kind": "state_variable", "name": "FantomToken.numberWhitelisted"}, {"id": "fragment-a50ad2f52d71f7cd252f", "kind": "state_variable", "name": "FantomToken.whitelist"}, {"id": "fragment-40878f6e165b97389d2f", "kind": "state_variable", "name": "FantomToken.tokensTradeable"}, {"id": "fragment-dc37f54b1b5546a2f9cc", "kind": "state_variable", "name": "FantomToken.isMigrationPhaseOpen"}, {"id": "fragment-829519d7254089dde500", "kind": "state_variable", "name": "FantomToken.balancesMinted"}, {"id": "fragment-818a2a60c8ff3c92dc39", "kind": "state_variable", "name": "FantomToken.balancesMintedByType"}, {"id": "fragment-8508e9fd2b766ac7ec98", "kind": "state_variable", "name": "FantomToken.MINIMUM_CONTRIBUTION"}, {"id": "fragment-b47648073aaddb7c2ce1", "kind": "state_variable", "name": "FantomToken.balancesMain"}, {"id": "fragment-1e9e0eb19b9e6cf0e2b6", "kind": "state_variable", "name": "FantomToken.ethContributed"}, {"id": "fragment-7a78356ab9d50b14ca34", "kind": "state_variable", "name": "FantomToken.tokensMain"}, {"id": "fragment-43013883a46af1d8bc5b", "kind": "state_variable", "name": "FantomToken.totalEthContributed"}], "provided_context": [{"id": "fragment-25c37eef1c0f0e10f201", "kind": "function", "name": "ethToTokens(uint256)", "source": "function ethToTokens(uint _eth) public view returns (uint tokens) {
