{"target": {"id": "fragment-255498ad02a5c50f9a32", "kind": "function", "contract": "FantomToken", "signature": "buyTokens()", "visibility": "private", "source": "function buyTokens() private {

        require(isMain());
        require(msg.value >= MINIMUM_CONTRIBUTION);
        require(whitelist[msg.sender]);

        uint tokens_available = TOKEN_MAIN_CAP.sub(tokensMain);

        // adjust tokens_available on first day, if necessary
        if (isMainFirstDay()) {
            uint tokens_available_first_day = firstDayTokenLimit().sub(balancesMain[msg.sender]);
            if (tokens_available_first_day < tokens_available) {
                tokens_available = tokens_available_first_day;
            }
        }

        require (tokens_available > 0);

        uint tokens_requested = ethToTokens(msg.value);
        uint tokens_issued = tokens_requested;

        uint eth_contributed = msg.value;
        uint eth_returned;

        if (tokens_requested > tokens_available) {
            tokens_issued = tokens_available;
            eth_returned = tokensToEth(tokens_requested.sub(tokens_available));
            eth_contributed = msg.value.sub(eth_returned);
        }

        balances[msg.sender] = balances[msg.sender].add(tokens_issued);
        balancesMain[msg.sender] = balancesMain[msg.sender].add(tokens_issued);
        tokensMain = tokensMain.add(tokens_issued);
        tokensIssuedTotal = tokensIssuedTotal.add(tokens_issued);

        ethContributed[msg.sender] = ethContributed[msg.sender].add(eth_contributed);
        totalEthContributed = totalEthContributed.add(eth_contributed);

        // ether transfers
        if (eth_returned > 0) msg.sender.transfer(eth_returned);
        wallet.transfer(eth_contributed);

        // log
        emit Transfer(0x0, msg.sender, tokens_issued);
        emit RegisterContribution(msg.sender, tokens_issued, eth_contributed, eth_returned);
    }", "state_reads": ["MINIMUM_CONTRIBUTION", "TOKEN_MAIN_CAP", "balances", "balancesMain", "ethContributed", "tokensIssuedTotal", "tokensMain", "totalEthContributed", "wallet", "whitelist"], "state_writes": ["balances", "balancesMain", "ethContributed", "tokensIssuedTotal", "tokensMain", "totalEthContributed"], "modifiers": [], "state_dependencies": [{"id": "ERC20Token.balances", "name": "balances", "declaration_id": "fragment-df3e94d520804e3d7356", "direct_writers": [{"fragment_id": "fragment-590e1b4283244cf4a5eb", "signature": "transfer(address,uint256)", "kind": "function"}, {"fragment_id": "fragment-0eaca0fab160e95edf7a", "signature": "transferFrom(address,address,uint256)", "kind": "function"}, {"fragment_id": "fragment-167f4a154e1c81e60fd6", "signature": "pMintTokens(uint256,address,uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-255498ad02a5c50f9a32", "signature": "buyTokens()", "kind": "function"}, {"fragment_id": "fragment-d185109cbff33c1977ca", "signature": "requestTokenExchange(uint256)", "kind": "function"}]}, {"id": "ERC20Token.tokensIssuedTotal", "name": "tokensIssuedTotal", "declaration_id": "fragment-1c2061b921a09cb050bb", "direct_writers": [{"fragment_id": "fragment-167f4a154e1c81e60fd6", "signature": "pMintTokens(uint256,address,uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-255498ad02a5c50f9a32", "signature": "buyTokens()", "kind": "function"}, {"fragment_id": "fragment-d185109cbff33c1977ca", "signature": "requestTokenExchange(uint256)", "kind": "function"}]}, {"id": "FantomToken.MINIMUM_CONTRIBUTION", "name": "MINIMUM_CONTRIBUTION", "declaration_id": "fragment-8508e9fd2b766ac7ec98", "direct_writers": [{"fragment_id": "fragment-266e06acf0415df21668", "signature": "slitherConstructorConstantVariables()", "kind": "function"}]}, {"id": "FantomToken.TOKEN_MAIN_CAP", "name": "TOKEN_MAIN_CAP", "declaration_id": "fragment-c5838278c8a1179dfc6e", "direct_writers": [{"fragment_id": "fragment-266e06acf0415df21668", "si